from bookings import load_bookings, ROWS
from deltas import nights_changes, biggest_rise

VALUES = [v for _, v in ROWS]
EXPECTED = [VALUES[i] - VALUES[i - 1] for i in range(1, len(VALUES))]


def test_number_of_changes():
    assert len(nights_changes(list(load_bookings()))) == len(ROWS) - 1


def test_values():
    assert nights_changes(list(load_bookings())) == EXPECTED


def test_two_items():
    assert nights_changes(list(load_bookings())[:2]) == EXPECTED[:1]


def test_biggest_rise():
    assert biggest_rise(list(load_bookings())) == max([c for c in EXPECTED if c > 0] or [0])


def test_single_item():
    assert nights_changes(list(load_bookings())[:1]) == [] and nights_changes([]) == []

